package com.eventforge.notification;
import com.eventforge.activity.EventActivityService; import com.eventforge.event.Event; import com.eventforge.domain.User; import com.eventforge.task.EventTask; import java.time.Instant; import java.time.LocalDate; import java.time.LocalDateTime; import java.time.ZoneOffset; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class NotificationService {
 private final NotificationRepository notifications; private final EventActivityService activities; public NotificationService(NotificationRepository notifications,EventActivityService activities){this.notifications=notifications;this.activities=activities;}
 /** Public integration point for feature services; recipients are explicitly supplied. */ public NotificationDto recordNotification(Event event,User recipient,NotificationType type,String message){if(event==null||recipient==null||type==null||message==null||message.isBlank())throw new IllegalArgumentException("event, recipient, type and message are required");Notification n=notifications.save(new Notification(event,recipient,type,message));activities.recordActivity(event,recipient,"Notification created",message);return NotificationDto.from(n);}
 /** Convenience integration point for notifications belonging to an event owner. */ public NotificationDto recordForEventOwner(Event event,NotificationType type,String message){return recordNotification(event,event.getOwner(),type,message);}
 /** Records one task deadline notification of a type per UTC day. */ public void recordTaskDeadline(EventTask task,NotificationType type,String message,Instant now){LocalDate day=now.atZone(ZoneOffset.UTC).toLocalDate(); LocalDateTime start=day.atStartOfDay(); LocalDateTime end=day.plusDays(1).atStartOfDay(); if(!notifications.existsByTask_IdAndTypeAndCreatedAtGreaterThanEqualAndCreatedAtLessThan(task.getId(),type,start,end)){Event event=task.getEvent(); Notification n=notifications.save(new Notification(event,event.getOwner(),task,type,message));activities.recordActivity(event,event.getOwner(),"TASK_"+type+"_NOTIFICATION",message);}}
 @Transactional(readOnly=true) public Page<NotificationDto> list(UUID userId,Pageable pageable){return notifications.findByRecipientId(userId,pageable).map(NotificationDto::from);}
 public NotificationDto markRead(UUID id,UUID userId){Notification n=notifications.findByIdAndRecipientId(id,userId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found"));n.markRead();activities.recordActivity(n.getEvent(),n.getRecipient(),"Notification marked read",n.getMessage());return NotificationDto.from(n);}
}
